@GetMapping("/{id}")
public ResponseEntity<JournalResponse> find(@PathVariable String id) {
    return journalService.findVisible(id)
        .map(ResponseEntity::ok)
        .orElseGet(() -> ResponseEntity.notFound().build());
}

@PostMapping
public ResponseEntity<JournalResponse> create(
        @Valid @RequestBody CreateJournalRequest request) {
    JournalResponse saved = journalService.create(request);
    URI location = URI.create("/journal/" + saved.id());
    return ResponseEntity.created(location).body(saved);
}
